function renderStats(){const e=document.getElementById("stats-grid");e&&"undefined"!=typeof SANTOSH_INFO&&(e.innerHTML=SANTOSH_INFO.quickStats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-val">${e.value}</div>\n            <div class="stat-lbl">${e.label}</div>\n        </div>\n    `).join(""))}function renderChampions(){const e=document.getElementById("champions-grid");e&&"undefined"!=typeof STATE_CHAMPIONS&&(e.innerHTML=STATE_CHAMPIONS.map(e=>`\n        <div class="champion-card">\n            <div class="card-header">\n                <h3>🥇 ${e.state}</h3>\n                <span class="titles-badge">${e.titles} Titles</span>\n            </div>\n            <p><strong>Runners-Up:</strong> ${e.runnersUp} times | <strong>Zone:</strong> ${e.region}</p>\n            <p class="era-text">${e.notableEra}</p>\n        </div>\n    `).join(""))}function renderPlayers(){const e=document.getElementById("players-grid");e&&"undefined"!=typeof NOTABLE_PLAYERS&&(e.innerHTML=NOTABLE_PLAYERS.map(e=>`\n        <div class="player-card">\n            <span class="role-tag">${e.role}</span>\n            <h3>⭐ ${e.name}</h3>\n            <p><strong>Represented:</strong> ${e.state}</p>\n            <p>${e.achievements}</p>\n        </div>\n    `).join(""))}function renderTimeline(){const e=document.getElementById("timeline-container");e&&"undefined"!=typeof TOURNAMENT_MILESTONES&&(e.innerHTML=TOURNAMENT_MILESTONES.map(e=>`\n        <div class="timeline-card">\n            <div class="timeline-year">${e.year}</div>\n            <div class="timeline-content">\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderReferences(){const e=document.getElementById("references-list");e&&"undefined"!=typeof REFERENCES&&(e.innerHTML=REFERENCES.map(e=>`\n        <li>\n            <a href="${e.link}" target="_blank" rel="noopener noreferrer">📚 ${e.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{const n=document.body.classList.toggle("light-theme");localStorage.setItem("theme",n?"light":"dark"),e.textContent=n?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderChampions(),renderPlayers(),renderTimeline(),renderReferences(),initThemeToggle()});